UPDATE dishes SET cultural_significance = 'Gazpacho is an Andalusian cold soup with roots in the Roman Empire. Originally a bread-based peasant soup, it evolved into a tomato-based refreshment after the Columbian Exchange.' WHERE name = 'Gazpacho' AND country = 'Spain' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Wiener Schnitzel is Austria''s national dish, a breaded veal cutlet protected by Austrian culinary law. Its origins may trace to Milan''s cotoletta, brought to Vienna in the 19th century.' WHERE name = 'Wiener Schnitzel' AND country = 'Austria' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Adana Kebab is named after the city of Adana in southern Turkey. Hand-minced lamb on a flat skewer grilled over charcoal is a symbol of Turkish grilling mastery, with geographical indication protection.' WHERE name = 'Adana Kebab' AND country = 'Turkey' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Turkish Breakfast (Kahvaltı) is an elaborate spread of cheeses, olives, eggs, and bread reflecting the Ottoman Empire''s culinary legacy. The word kahvaltı literally means "before coffee."' WHERE name = 'Turkish Breakfast' AND country = 'Turkey' AND cultural_significance IS NULL;

-- Asia
UPDATE dishes SET cultural_significance = 'Kung Pao Chicken is a Sichuan classic named after Qing Dynasty governor Ding Baozhen (Kung Pao). The dish''s numbing-spicy flavor profile defines Sichuan cuisine''s bold character.' WHERE name = 'Kung Pao Chicken' AND country = 'China' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Har Gow (crystal shrimp dumplings) are the crown jewel of Cantonese dim sum. The translucent pleated wrapper is a test of a dim sum chef''s skill, requiring at least 10 folds.' WHERE name = 'Har Gow' AND country = 'China' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Chai is India''s national drink, consumed billions of times daily. The British introduced tea cultivation, but Indians transformed it with milk, sugar, and spices into an entirely new cultural institution.' WHERE name = 'Chai' AND country = 'India' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Masala Dosa is a South Indian fermented rice-and-lentil crêpe filled with spiced potatoes. It originated in Udupi, Karnataka, and has become one of India''s most popular breakfast dishes nationwide.' WHERE name = 'Masala Dosa' AND country = 'India' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Matcha Latte combines Japan''s centuries-old tea ceremony tradition with modern café culture. Matcha was brought to Japan by Zen Buddhist monks from China in the 12th century.' WHERE name = 'Matcha Latte' AND country = 'Japan' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Japanese Curry Rice (Kare Raisu) was introduced by the British Royal Navy via India in the Meiji era. Japan adapted it into a milder, sweeter version that is now the country''s most popular comfort food.' WHERE name = 'Japanese Curry Rice' AND country = 'Japan' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Tonkotsu Ramen originated in Fukuoka in 1937. The rich pork bone broth, simmered for 12+ hours, represents the dedication and perfectionism of Japanese ramen craftsmanship (shokunin spirit).' WHERE name = 'Tonkotsu Ramen' AND country = 'Japan' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Kimchi Jjigae is Korea''s ultimate comfort stew, made with aged kimchi. It represents the Korean philosophy of transforming fermented ingredients into deeply flavored, communal dishes.' WHERE name = 'Kimchi Jjigae' AND country = 'South Korea' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Tom Yum Goong is Thailand''s most famous soup, embodying the Thai flavor balance of sour, spicy, salty, and sweet. It was submitted for UNESCO Intangible Cultural Heritage recognition.' WHERE name = 'Tom Yum Goong' AND country = 'Thailand' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Thai Iced Tea was created using Ceylon tea mixed with star anise, tamarind, and orange food coloring. Its distinctive orange hue and sweet creamy taste have made it a global Thai restaurant staple.' WHERE name = 'Thai Iced Tea' AND country = 'Thailand' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Pho Bo is Vietnam''s national soup, originating in early 20th-century Hanoi. It fuses French beef stock traditions with Vietnamese herbs and rice noodles, symbolizing the country''s culinary resilience.' WHERE name = 'Pho Bo' AND country = 'Vietnam' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Banh Mi is a Vietnamese baguette sandwich born from French colonialism. It perfectly illustrates how Vietnam absorbed and transformed colonial ingredients into something uniquely Vietnamese.' WHERE name = 'Banh Mi' AND country = 'Vietnam' AND cultural_significance IS NULL;

-- Americas & Oceania
UPDATE dishes SET cultural_significance = 'Southern Fried Chicken is an American culinary icon with roots in Scottish and West African frying traditions. Enslaved African cooks perfected the seasoning techniques that define the dish today.' WHERE name = 'Southern Fried Chicken' AND country = 'United States' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Jerk Chicken is Jamaica''s most iconic dish, with roots in the Maroon communities of escaped enslaved Africans. The jerk technique of smoking meat over pimento wood dates to the 17th century.' WHERE name = 'Jerk Chicken' AND country = 'Jamaica' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Rum Punch is the Caribbean''s quintessential cocktail, following the centuries-old rhyme: "One of sour, two of sweet, three of strong, four of weak." It embodies the rum-producing heritage of the islands.' WHERE name = 'Rum Punch' AND country = 'Caribbean' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Caipirinha is Brazil''s national cocktail, made with cachaça, lime, and sugar. It originated among São Paulo''s sugar cane farmers and is now a global symbol of Brazilian joie de vivre.' WHERE name = 'Caipirinha' AND country = 'Brazil' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Arepas are a pre-Columbian staple of the indigenous peoples of Venezuela and Colombia. Made from ground maize, they are a daily bread that predates European contact by thousands of years.' WHERE name = 'Arepas' AND country = 'Colombia' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Pavlova is a meringue-based dessert claimed by both Australia and New Zealand, created to honor Russian ballerina Anna Pavlova during her 1920s tour of Oceania.' WHERE name = 'Pavlova' AND country = 'Australia' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'The Australian Meat Pie is the country''s unofficial national dish, consumed at football matches, bakeries, and service stations. It is a descendant of British pie traditions adapted to Australian tastes.' WHERE name = 'Meat Pie' AND country = 'Australia' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'The Flat White coffee originated in the café cultures of Australia and New Zealand in the 1980s. It has since conquered global coffee chains and represents Antipodean coffee innovation.' WHERE name = 'Flat White' AND country = 'New Zealand' AND cultural_significance IS NULL;
UPDATE dishes SET cultural_significance = 'Hangi is the traditional Māori earth oven cooking method, where food is buried in a pit with heated stones. It is central to Māori ceremonies and represents the deep Māori connection to the land.' WHERE name = 'Hangi' AND country = 'New Zealand' AND cultural_significance IS NULL;

-- ===== ENRICH RECIPES.history (thin entries) =====

UPDATE recipes SET history = 'Accra Plantain (fried ripe plantain fritters) is one of Central Africa''s most popular snacks. Originating among the Bamiléké and Douala peoples of Cameroon, these golden fritters are a staple of roadside vendors and family celebrations, often served with beans or pepper sauce.' WHERE name = 'Accra Plantain' AND country = 'Cameroon' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Garba is named after the Hausa and Nigerian vendors who popularized the dish in Abidjan''s Adjamé market. This pairing of attiéké (fermented cassava couscous) with fried tuna became the most affordable and beloved street meal in Ivory Coast.' WHERE name = 'Garba Tuna' AND country = 'Ivory Coast' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Liboke is one of the Congo''s most elegant preparations—fish, meat, or chicken seasoned and steamed in banana leaves over charcoal. The technique preserves moisture and infuses the dish with a smoky, herbaceous aroma unique to Central African cuisine.' WHERE name = 'Liboke Congolais' AND country = 'DRC' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Eru (Gnetum africanum) is a prized wild forest green from Cameroon''s Southwest and Littoral regions. The laborious preparation—slicing the tough leaves into thin strips—is traditionally a communal women''s activity. Combined with waterleaf, crayfish, and palm oil, it creates a uniquely textured stew.' WHERE name = 'Eru Wild Spinach' AND country = 'Cameroon' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Pastilla (Bastilla) is Morocco''s most refined dish, a sweet-savory pigeon or chicken pie layered with almonds, cinnamon, and phyllo-like warqa pastry. Originally from Fez and rooted in Andalusian Moorish cuisine, it was brought by Muslims expelled from Spain in the 15th century.' WHERE name = 'Pastilla Fassia' AND country = 'Morocco' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Suqaar is everyday Somali home cooking at its finest—small cubes of meat quickly sautéed with vegetables and spices. The name means "small pieces" in Somali, and the dish embodies the practical, flavorful approach of Somali household cuisine.' WHERE name = 'Suqaar Quick' AND country = 'Somalia' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Thiakry is Senegal''s beloved celebration dessert—millet couscous mixed with sweetened yogurt, vanilla, and nutmeg, served chilled. It is prepared for naming ceremonies (nguenté), religious holidays, and family gatherings throughout Senegal and the Gambia.' WHERE name = 'Thiakry Dessert' AND country = 'Senegal' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Cachupa is Cape Verde''s national dish, a slow-cooked stew of hominy corn, beans, and meat or fish. "Cachupa Rica" is the festive version with multiple meats, while "Cachupa Pobre" is the everyday vegetarian version—reflecting the archipelago''s history of scarcity and celebration.' WHERE name = 'Cachupa Cape Verdean' AND country = 'Cape Verde' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Nyembwe (chicken in palm nut sauce) has been the foundation of Fang and Myene cooking in Gabon for centuries. The rich, orange-red palm fruit sauce is laboriously extracted from palm nuts and represents the culinary wealth of the Gabonese rainforest.' WHERE name = 'Nyembwe Gabonais' AND country = 'Gabon' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Mandazi are sweet, slightly cardamom-spiced fried dough eaten across East Africa as the perfect chai companion. From Mombasa to Dar es Salaam, these triangular fritters are the quintessential East African breakfast and teatime snack.' WHERE name = 'Mandazi Kenyan' AND country = 'Kenya' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Tibs is Ethiopia''s go-to restaurant dish—sizzling cubes of meat sautéed with rosemary, jalapeños, and onions, served on a hot clay plate. Every Ethiopian eatery (bunna bet) serves its own version, from the mild Addis style to the fiery Gurage preparation.' WHERE name = 'Tibs Sizzling' AND country = 'Ethiopia' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Sharba is Libya''s quintessential soup, a rich lamb and tomato broth with orzo pasta, chickpeas, and a blend of Libyan spices. It is served daily during Ramadan to break the fast and is the cornerstone of Libyan home cooking.' WHERE name = 'Sharba Libiyya' AND country = 'Libya' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Luwombo was created by Kabaka (King) Mwanga II''s personal chef in the 1880s Buganda Kingdom. Food steamed in banana leaves was originally a royal court technique that has since become Uganda''s most prestigious dish for special occasions.' WHERE name = 'Luwombo Royal' AND country = 'Uganda' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Chakchouka (shakshuka) originated in Ottoman-era Algeria, where eggs were poached in a spiced tomato and pepper sauce. The dish spread across North Africa and the Middle East, but Algeria claims it as an original creation, with each city adding its own twist.' WHERE name = 'Chakchouka Alger' AND country = 'Algeria' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Kenyan Samosa was brought by Indian traders along the Swahili coast and adopted with distinctly Kenyan spicing—more chili, less sweetness. Today it is the country''s most popular street snack, found at every kiosk from Nairobi to Mombasa.' WHERE name = 'Samosa Kenyan' AND country = 'Kenya' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Hawawshi originated in Alexandria and quickly became Cairo''s favorite street food. This spiced minced meat stuffed into Egyptian baladi bread and baked or grilled represents the hearty, no-frills approach of Egyptian working-class cuisine.' WHERE name = 'Hawawshi Cairo' AND country = 'Egypt' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Injera is Ethiopia''s ancient staple, a spongy fermented flatbread made from teff flour. It serves as both plate and utensil—diners tear off pieces to scoop up stews (wot). The fermentation process, using a sourdough-like starter called ersho, has been practiced for thousands of years.' WHERE name = 'Injera' AND country = 'Ethiopia' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Ndolé is Cameroon''s national dish, a bitterleaf stew from the Douala people of the Littoral region. The bitter leaves must be washed and boiled multiple times to remove their natural bitterness, a process that represents the patience and skill central to Cameroonian cooking.' WHERE name = 'Ndolé National' AND country = 'Cameroon' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Satay originated among Javanese street vendors in the 19th century, inspired by Middle Eastern kebabs brought by Arab traders. It has since become a pan-Southeast Asian staple, with each country—Indonesia, Malaysia, Thailand, and Singapore—claiming its own distinctive version.' WHERE name = 'Satay' AND country = 'Indonesia' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Molokhia (jute leaves soup) dates to ancient Egypt—legend says it was named "the king''s vegetable" because Pharaohs reserved it for royalty. Today it is Egypt''s most popular home-cooked dish, with every family guarding their grandmother''s recipe.' WHERE name = 'Molokhia Egyptian' AND country = 'Egypt' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Rechta is Algeria''s most prestigious pasta dish, requiring hours of hand-rolling thin noodles from semolina dough. It is the centerpiece of Algerian weddings and Mawlid celebrations, representing the pinnacle of Algerian culinary craft and female expertise.' WHERE name = 'Rechta Algérienne' AND country = 'Algeria' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Suya is a beloved Nigerian street food originating from the Hausa people of northern Nigeria. Thinly sliced beef coated in yaji (a spice mix of ground peanuts, ginger, paprika, and chili) and grilled over charcoal has become a nationwide obsession sold at roadside mai-suya stands.' WHERE name = 'Suya' AND country = 'Nigeria' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Harira is traditionally served to break the fast during Ramadan in Morocco. This rich tomato-based soup with lentils, chickpeas, and lamb is mentioned in medieval Moroccan cookbooks and represents centuries of Maghrebi culinary tradition.' WHERE name = 'Harira' AND country = 'Morocco' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Kitfo is the ultimate Gurage delicacy from southern Ethiopia—finely minced raw beef mixed with mitmita (chili powder) and niter kibbeh (spiced clarified butter). It can be eaten raw (lebleb), lightly warmed (leb leb), or fully cooked, and it defines Gurage identity.' WHERE name = 'Kitfo' AND country = 'Ethiopia' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Plasas is the heart of Sierra Leonean cuisine—a rich slow-cooked sauce of pounded cassava or potato leaves, palm oil, and dried fish. It is served at every major occasion from weddings to funerals and represents the communal cooking traditions of the Mende and Temne peoples.' WHERE name = 'Plasas' AND country = 'Sierra Leone' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Pupusas are the national dish of El Salvador with roots in pre-Columbian Pipil cuisine. Archaeological evidence shows that stuffed corn cakes have been made in this region for over 2,000 years. November 13 is officially National Pupusa Day in El Salvador.' WHERE name = 'Pupusas' AND country = 'El Salvador' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Brik is Tunisia''s most famous appetizer—a thin malsouka pastry shell filled with egg, tuna, capers, and harissa, then deep-fried until golden. The skill is in keeping the egg yolk runny inside the crispy shell, a true test of Tunisian culinary finesse.' WHERE name = 'Brik Tunisien' AND country = 'Tunisia' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Bunny Chow was created by Durban''s Indian community during apartheid-era restrictions, when hollowed-out bread loaves became portable curry containers. This ingenious South African creation transcended racial barriers to become a beloved national street food.' WHERE name = 'Bunny Chow Durban' AND country = 'South Africa' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Laksa is a spicy noodle soup that blends Malay and Chinese culinary traditions, born from the Peranakan (Straits Chinese) communities of Malaysia and Singapore. Each region—Penang, Sarawak, Katong—has its own fiercely defended version.' WHERE name = 'Laksa' AND country = 'Malaysia' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Moussaka was popularized in its modern layered form by Greek chef Nikolaos Tselementes in the 1920s, who added béchamel sauce to the traditional Ottoman eggplant and meat dish. It has since become Greece''s most internationally recognized casserole.' WHERE name = 'Moussaka' AND country = 'Greece' AND LENGTH(history) < 80;
UPDATE recipes SET history = 'Koshari is Cairo''s beloved street food, a unique fusion of Indian lentils, Italian pasta, Egyptian rice, and Middle Eastern spiced tomato sauce, topped with crispy onions. It emerged in the 19th century from Egypt''s cosmopolitan culinary landscape.' WHERE name = 'Koshari' AND country = 'Egypt' AND LENGTH(history) < 80;
